    # Isolate the rectangular board of background color 1.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    board = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(board), len(board[0])

    inside = {}
    for r in range(H):
        for c in range(W):
            v = board[r][c]
            if v != 1:
                inside.setdefault(v, []).append((r, c))

    outside = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v and not (r0 <= r <= r1 and c0 <= c <= c1):
                outside.setdefault(v, []).append((r, c))

    # Single-cell colors on the board are orientation markers. The external
    # markers specify their target corners.
    markers = [v for v in outside if len(inside.get(v, [])) == 1]
    if not markers:
        return board

    all_pts = [p for v in markers for p in outside[v]]
    minr = min(r for r, c in all_pts)
    maxr = max(r for r, c in all_pts)
    minc = min(c for r, c in all_pts)
    maxc = max(c for r, c in all_pts)

    targets = {}
    for v in markers:
        r, c = outside[v][0]
        targets[v] = (0 if r - minr <= maxr - r else 1,
                      0 if c - minc <= maxc - c else 1)

    def rotate_cw(a):
        return [list(row) for row in zip(*a[::-1])]

    candidates = []
    a = board
    for _ in range(4):
        candidates.append(a)
        a = rotate_cw(a)
    a = [row[::-1] for row in board]
    for _ in range(4):
        candidates.append(a)
        a = rotate_cw(a)

    best, best_score = board, -1
    for a in candidates:
        ah, aw = len(a), len(a[0])
        score = 0
        for v in markers:
            r, c = next((r, c) for r in range(ah) for c in range(aw) if a[r][c] == v)
            target_r, target_c = targets[v]
            corner = (0 if r < ah / 2 else 1, 0 if c < aw / 2 else 1)
            if corner == (target_r, target_c):
                score += 1
        if score > best_score:
            best, best_score = a, score

    return best
